<template>
  <div class="evaluation-module-page page-container">
    <header class="module-header"><div><div class="header-title"><el-icon><Aim /></el-icon><h1>预测偏差分析工作台</h1><el-tag type="warning" effect="plain">{{ summary[0].value }} 个异常样本</el-tag></div><p>联动趋势分析异常数据，筛选高偏差样本并定位数据、标注、拟合与市场波动根因</p></div><div class="header-actions"><el-button :icon="Setting" @click="router.push('/prediction-evaluation/config#bias')">偏差规则</el-button><el-button :icon="Document" @click="generateReport">生成分析报告</el-button></div></header>
    <div class="page-workspace"><TaskList/><main class="business-content">
      <section class="context-bar surface"><div><small>当前分析任务</small><strong>{{currentTask?.name}} · {{currentTask?.version}}</strong></div><div class="header-actions"><el-select v-model="period" style="width:140px"><el-option label="最近 7 天" value="7d"/><el-option label="最近 30 天" value="30d"/><el-option label="全部周期" value="all"/></el-select><el-button type="primary" :icon="Aim" :loading="detecting" @click="detectBias">一键偏差检测</el-button></div></section>
      <div class="metric-grid"><article v-for="m in summary" :key="m.name" class="metric-card"><div class="metric-head"><span>{{m.name}}</span></div><strong :class="m.tone">{{m.value}}</strong><small>{{m.note}}</small></article></div>
      <el-alert v-if="biasMessage" class="bias-message" :title="biasMessage" type="info" :closable="false" show-icon />
      <el-card v-if="generatedReport" class="report-result" shadow="never">
        <div class="report-result-main">
          <div>
            <b>报告已生成</b>
            <p>报告编号：{{ generatedReport.id }}；已保存到系统报告记录，可在图表报告中心查看。</p>
          </div>
          <div class="header-actions">
            <el-button size="small" @click="router.push({ path: '/charts', query: { datasetId: generatedReport.datasetId } })">查看报告</el-button>
            <el-button size="small" type="primary" @click="downloadReport">下载 JSON</el-button>
          </div>
        </div>
      </el-card>
      <div class="equal-column"><section class="surface"><div class="section-head"><div><h2>全局偏差来源分布</h2><p>按根因贡献度自动归因</p></div></div><el-empty v-if="!sources.length" :description="emptyReason('执行偏差检测后，系统会根据真实异常样本计算来源分布；当前无数据不是系统错误。')" :image-size="70"/><div v-else class="donut-layout"><div class="donut"><span><b>{{ summary[0].value }}</b>异常样本</span></div><div class="legend"><div v-for="s in sources" :key="s.name"><i :style="{background:s.color}"></i><span>{{s.name}}</span><b>{{s.value}}%</b></div></div></div></section><section class="surface"><div class="section-head"><div><h2>高频偏差场景</h2><p>按影响样本量与业务影响排序</p></div></div><el-empty v-if="!scenes.length" :description="emptyReason('只有检测到可归因的偏差样本后才会显示；当前无数据不是系统错误。')" :image-size="70"/><div v-else class="list-rows"><div v-for="(s,i) in scenes" :key="s.name"><span class="number-icon">{{i+1}}</span><div><b>{{s.name}}</b><small>{{s.desc}}</small></div><strong>{{s.count}}</strong></div></div></section></div>
      <section class="surface"><div class="section-head"><div><h2>偏差时段趋势</h2><p>预测值与实际值差异幅度变化</p></div><el-segmented v-model="trendType" :options="['偏差率','偏差量']" size="small"/></div><div v-if="trendSamples.length" class="bias-trend"><div v-for="row in trendSamples.slice(-24)" :key="row.id" class="trend-bar"><i :style="{height:`${Math.min(100, Math.max(4, Number(row.biasValue || 0)))}%`}"/><small>{{row.period || row.id}}</small></div></div><el-empty v-else :description="emptyReason('需要预测值与同日期实际值后才能计算趋势；当前无数据不是系统错误。')" :image-size="70"/></section>
      <section class="surface table-surface"><div class="section-head"><div><h2>高偏差预测样本</h2><p>超过当前偏差规则阈值的明细结果</p></div><div class="header-actions"><el-input v-model="sampleKeyword" :prefix-icon="Search" placeholder="搜索样本或归因" style="width:210px"/><el-button :icon="Download" :disabled="!samples.length" @click="exportSamples">导出样本</el-button></div></div><el-table :data="filteredSamples" height="310" :empty-text="emptyReason('当前任务没有超过阈值的偏差样本，或尚未回填与预测日期匹配的实际值；当前无数据不是系统错误。')"><el-table-column prop="id" label="样本 ID" width="110"/><el-table-column prop="period" label="偏差时段" width="145"/><el-table-column prop="actual" label="实际值"/><el-table-column prop="predicted" label="预测值"/><el-table-column label="偏差幅度"><template #default="{row}"><b class="negative">{{row.bias}}</b></template></el-table-column><el-table-column label="偏差类型"><template #default="{row}"><el-tag size="small" :type="row.level==='高'?'danger':'warning'">{{row.type}}</el-tag></template></el-table-column><el-table-column prop="source" label="根因归因" min-width="140"/><el-table-column label="操作" width="100"><template #default="{row}"><el-button link type="primary" @click="inspect(row)">根因详情</el-button></template></el-table-column></el-table></section>
    </main></div>
    <el-drawer v-model="detailVisible" title="样本根因分析" size="480px"><template v-if="selectedSample"><el-descriptions :column="1" border><el-descriptions-item label="样本 ID">{{selectedSample.id}}</el-descriptions-item><el-descriptions-item label="偏差幅度">{{selectedSample.bias}}</el-descriptions-item><el-descriptions-item label="归因结果">{{selectedSample.source}}</el-descriptions-item></el-descriptions><el-alert class="cause-alert" title="建议检查该时段促销活动与渠道库存上报延迟，并提高活动特征权重。" type="warning" :closable="false" show-icon/></template></el-drawer>
  </div>
</template>
<script setup>
const generatedReport=ref(null)
import { computed,defineComponent,h,ref,watch } from 'vue';import { useRouter } from 'vue-router';import { ElButton,ElEmpty,ElInput,ElMessage,ElTag } from 'element-plus';import { Aim,Document,Download,Refresh,Search,Setting } from '@element-plus/icons-vue';import { useEvaluationTasks } from '../composables/useEvaluationTasks';import request from '../utils/request';import '../assets/styles/evaluation-pages.css'
const router=useRouter();const {loading,selectedId,keyword,visibleTasks,currentTask,loadTasks}=useEvaluationTasks();const savedBiasState=(()=>{try{return JSON.parse(localStorage.getItem('river_prediction_bias_state')||'{}')}catch{return {}}})();const period=ref(savedBiasState.period||'7d'),trendType=ref(savedBiasState.trendType||'偏差率'),detecting=ref(false),sampleKeyword=ref(savedBiasState.sampleKeyword||''),detailVisible=ref(false),selectedSample=ref(null),biasMessage=ref(''),evaluationAvailable=ref(null);const summary=ref([{name:'高偏差样本',value:'—',note:'执行偏差检测后生成',tone:'negative'},{name:'平均偏差幅度',value:'—',note:'来自后端检测结果',tone:'positive'},{name:'严重偏差场景',value:'—',note:'来自后端检测结果',tone:'negative'},{name:'已完成归因',value:'—',note:'来自后端检测结果',tone:'positive'}]);const sources=ref([]),scenes=ref([]),samples=ref([]),trendSamples=ref([]);const filteredSamples=computed(()=>samples.value.filter(r=>!sampleKeyword.value||`${r.id}${r.source}${r.type}`.includes(sampleKeyword.value)));const emptyReason=detail=>{if(!selectedId.value)return '请先选择预测任务，再执行偏差检测；当前无数据不是系统错误。';if(evaluationAvailable.value===false)return '当前预测任务没有与预测日期匹配的实际值，属于正常业务状态，不是系统错误。请回填 actual_value 后重新执行偏差检测。';if(biasMessage.value)return `${detail} ${biasMessage.value}`;return detail};function applyBiasResult(result){evaluationAvailable.value=result.evaluationAvailable??true;biasMessage.value=result.message||'';samples.value=result.samples||result.outliers||[];trendSamples.value=result.trend||samples.value;summary.value[0].value=String(result.highBiasCount??samples.value.length);summary.value[1].value=result.averageBias==null?'—':`${result.averageBias}%`;summary.value[2].value=String(result.severeScenarioCount??'—');summary.value[3].value=result.attributionRate==null?'—':`${result.attributionRate}%`;sources.value=result.sources||[];scenes.value=result.scenes||[]}async function detectBias(){if(!selectedId.value)return ElMessage.warning('请选择预测任务');detecting.value=true;try{const result=await request.post(`/v1/predictions/${selectedId.value}/bias-detection`);applyBiasResult(result);if(result.evaluationAvailable===false)ElMessage.info(result.message||'检测完成，等待实际数据回填后再进行偏差评估');else ElMessage.success('偏差检测完成，结果已保存并返回')}catch(e){ElMessage.error(`偏差检测失败：${e.message||'后端接口不可用'}`)}finally{detecting.value=false}}async function loadExistingBias(){if(!selectedId.value)return;try{const result=await request.post(`/v1/predictions/${selectedId.value}/bias-detection`);applyBiasResult(result)}catch(e){biasMessage.value='偏差检测暂未完成，请点击“一键偏差检测”重新执行'}}async function generateReport(){try{if(!currentTask.value?.datasetId)return ElMessage.warning('当前任务没有关联数据集');generatedReport.value=await request.post(`/v1/charts/reports?datasetId=${currentTask.value.datasetId}&reportType=BIAS`);ElMessage.success(`报告已生成，编号 ${generatedReport.value.id}`)}catch(e){ElMessage.error(`报告生成失败：${e.message||'后端接口不可用'}`)}}function downloadReport(){if(!generatedReport.value)return;const u=URL.createObjectURL(new Blob([JSON.stringify(generatedReport.value,null,2)],{type:'application/json;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download=`偏差分析报告-${generatedReport.value.id}.json`;a.click();URL.revokeObjectURL(u)}function inspect(row){selectedSample.value=row;detailVisible.value=true}function exportSamples(){if(!samples.value.length)return ElMessage.warning('暂无偏差样本');const rows=samples.value.map(Object.values).map(v=>v.join(',')).join('\n');const u=URL.createObjectURL(new Blob([`\uFEFF样本ID,时段,实际值,预测值,偏差,等级,类型,归因\n${rows}`],{type:'text/csv'}));const a=document.createElement('a');a.href=u;a.download='高偏差预测样本.csv';a.click();URL.revokeObjectURL(u)}watch([period,trendType,sampleKeyword],()=>localStorage.setItem('river_prediction_bias_state',JSON.stringify({period:period.value,trendType:trendType.value,sampleKeyword:sampleKeyword.value})))
const TaskList=defineComponent({setup(){return()=>h('aside',{class:'task-sidebar'},[h('div',{class:'section-head'},[h('div',[h('h2','待分析任务'),h('p',`${visibleTasks.value.length} 个预测任务`)]),h(ElButton,{circle:true,icon:Refresh,loading:loading.value,onClick:loadTasks})]),h(ElInput,{modelValue:keyword.value,'onUpdate:modelValue':v=>keyword.value=v,prefixIcon:Search,placeholder:'搜索任务',clearable:true}),h('div',{class:'task-list'},visibleTasks.value.length?visibleTasks.value.map(t=>h('button',{class:['task-item',{active:selectedId.value===t.id}],onClick:()=>selectedId.value=t.id},[h('div',{class:'task-head'},[h('b',t.name),h(ElTag,{size:'small',type:t.status==='待优化'?'warning':'info'},()=>t.status)]),h('div',{class:'task-meta'},[h('span',t.model),h('span',t.version)]),h('div',{class:'task-stats'},[h('span',t.biasSampleCount == null ? '未检测' : `异常样本 ${t.biasSampleCount}`),h('span',`MAPE ${t.mape??'--'}%`)])])):h(ElEmpty,{imageSize:60,description:'暂无任务'})),h('div',{class:'task-source'},'异常数据承接自模块 4 趋势分析与可视化')])}})
watch(selectedId, loadExistingBias, { immediate: true })
</script><style scoped>.cause-alert{margin-top:18px}.bias-message{margin-bottom:16px}.metric-grid{grid-template-columns:repeat(4,1fr)}.bias-trend{display:flex;align-items:flex-end;gap:8px;height:190px;padding:16px 10px;border-top:1px solid #f2f3f5}.trend-bar{display:flex;min-width:22px;height:100%;flex:1;flex-direction:column;justify-content:flex-end;align-items:center;gap:6px}.trend-bar i{display:block;width:100%;min-height:4px;border-radius:4px 4px 0 0;background:linear-gradient(180deg,#ff7d00,#f53f3f)}.trend-bar small{max-width:58px;overflow:hidden;color:#86909c;font-size:10px;text-overflow:ellipsis;white-space:nowrap}</style>
